with (OUT/'FIELD_MAPPING.tsv').open('w',encoding='utf-8-sig',newline='') as f:
    writer=csv.DictWriter(f,fieldnames=list(maps[0]),delimiter='\t');writer.writeheader();writer.writerows(maps)
save('field_mapping.json',maps)
print('INVENTORY_BOOKS',len(books),'FIELD_ROWS',len(maps))
